<script setup lang="ts">
import { computed, ref } from 'vue'
import Icon from './PrototypeIcon.vue'
import { departments, type HomeAction } from './data'
import { departmentDoctors, departmentProfiles, type DepartmentMode } from './department-data'
const emit = defineEmits<{ action: [action: HomeAction]; back: []; select: [department: string, doctor?: string] }>()
const selectedName = ref(departments[0]!.name), mode = ref<DepartmentMode>('ONLINE')
const selected = computed(() => departments.find(item => item.name === selectedName.value) ?? departments[0]!)
const profile = computed(() => departmentProfiles[selected.value.name]!), doctors = computed(() => departmentDoctors[selected.value.name] ?? [])
const todayDoctors = computed(() => doctors.value.filter(item => item.today && item.mode === mode.value)), otherDoctors = computed(() => doctors.value.filter(item => !item.today))
function choose(name: string) { selectedName.value = name; mode.value = 'ONLINE' }
function register(doctor?: string) { emit('select', selected.value.name, doctor); emit('action', 'registration') }
</script>
<template>
  <section class="ph-dept-v-b" data-testid="department-page" aria-labelledby="department-page-title"><header class="ph-dept-b-hero"><div><span class="ph-eyebrow">CARE SCHEDULE · B</span><h1 id="department-page-title">找到今天适合你的门诊</h1><p>切换科室与服务方式，直接查看可用的出诊安排。</p></div><button class="ph-dept-b-ai" @click="emit('action', 'ai')"><Icon name="sparkles" /> AI 导诊</button></header><div class="ph-dept-b-board"><aside class="ph-dept-b-list"><h2>科室导航</h2><button v-for="item in departments" :key="item.name" :class="{ active: item.name === selected.name }" @click="choose(item.name)"><span>{{ item.name }}</span><small>{{ item.count }} 位医生</small><Icon name="chevron" /></button></aside><main class="ph-dept-b-main"><section class="ph-dept-b-overview"><div><span class="ph-dept-b-overview-icon"><Icon :name="selected.icon" /></span><div><span class="ph-eyebrow">{{ selected.detail }}</span><h2>{{ selected.name }}</h2><p>{{ profile.description }}</p></div></div><div class="ph-dept-b-overview-tags"><span v-for="item in profile.specialties" :key="item">{{ item }}</span></div></section><section class="ph-dept-b-schedule"><div class="ph-dept-b-heading"><div><span class="ph-eyebrow">TODAY</span><h2>今日出诊安排</h2></div><div class="ph-dept-mode-switch" role="tablist" aria-label="今日出诊方式"><button role="tab" :aria-selected="mode === 'ONLINE'" @click="mode = 'ONLINE'">线上出诊</button><button role="tab" :aria-selected="mode === 'OFFLINE'" @click="mode = 'OFFLINE'">线下出诊</button></div></div><div class="ph-dept-b-rows"><article v-for="doctor in todayDoctors" :key="doctor.id" class="ph-dept-b-row"><span class="ph-dept-doctor-avatar">{{ doctor.name[0] }}</span><div><h3>{{ doctor.name }} <small>{{ doctor.title }}</small></h3><p>{{ doctor.specialty }}</p></div><span class="ph-dept-b-row-time"><strong>{{ doctor.time }}</strong><small>{{ doctor.place }} · 剩余 {{ doctor.slots }} 个号</small></span><button class="ph-primary" @click="register(doctor.name)">立即挂号 <Icon name="arrow" /></button></article><p v-if="!todayDoctors.length" class="ph-dept-empty">当前方式暂无今日出诊医生。</p></div></section><section class="ph-dept-b-team"><div class="ph-dept-b-heading"><div><span class="ph-eyebrow">MORE DOCTORS</span><h2>医生列表</h2></div></div><div class="ph-dept-b-team-list"><article v-for="doctor in otherDoctors" :key="doctor.id"><span class="ph-dept-doctor-avatar muted">{{ doctor.name[0] }}</span><div><h3>{{ doctor.name }} <small>{{ doctor.title }}</small></h3><p>{{ doctor.specialty }} · {{ doctor.time }}</p></div><button class="ph-dept-appointment" @click="register(doctor.name)">预约 <Icon name="arrow" /></button></article></div></section></main></div></section>
</template>
